# Python script to parse logged data and identify potential tailgating attempts:

import re

# Function to parse the log file and identify tailgating attempts
def detect_tailgating(log_file_path):
    with open(log_file_path, 'r') as file:
        access_logs = file.readlines()

    # Regular expression to find access logs with the same UID but different timestamps
    pattern = r'UID: ([0-9A-F ]+)'
    access_dict = {}

    for log in access_logs:
        match = re.search(pattern, log)
        if match:
            uid = match.group(1).strip()
            if uid not in access_dict:
                access_dict[uid] = []
            access_dict[uid].append(log)

    # Identify potential tailgating attempts
    for uid, logs in access_dict.items():
        if len(logs) > 1:
            print(f"Potential tailgating attempt detected for UID: {uid}")
            for log in logs:
                print(log)

# Assuming the log file is named 'rfid_log.txt'
