public class MonteCarloPi {

    public static void main(String[] args) {

        // Create a Scanner object for user input
        Scanner sc = new Scanner(System.in);

        // Prompt the user for the number of experiments
        System.out.print("Enter the number of experiments to approximate Pi: ");

        // Handle invalid input
        while (!sc.hasNextInt()) {
            System.out.print("Invalid input. Please enter a valid integer: ");
            sc.next();
        }

        // Store the number of experiments as an integer
        int experiments = sc.nextInt();

        // Initialize variables
        int insideCircle = 0;

        // Loop through the number of experiments
        for (int i = 1; i <= experiments; i++) {

            // Generate random x and y coordinates between -1 and 1
            double x = Math.random() * 2 - 1;
            double y = Math.random() * 2 - 1;

            // Calculate the distance from (x, y) to the origin
            double distance = Math.sqrt(Math.pow(x, 2) + Math.pow(y, 2));

            // Check if the point is inside the circle
            if (distance <= 1) {
                insideCircle++;
            }
        }

        // Calculate the estimated value of Pi using the formula
        double pi = 4 * ((double) insideCircle / experiments);

        // Output the estimated value of Pi
        System.out.println("The estimated value of Pi is: " + pi);

        // Close the Scanner object
        sc.close();
    }

