import random

def generate_matrix():
    matrix = [[0 for _ in range(5)] for _ in range(5)]

    # Generate unique numbers for each row and column
    for i in range(5):
        unique_numbers = set()
        while len(unique_numbers) < 2:
            unique_numbers.add(random.randint(-100, 100))
        for j in range(5):
            if j == i:
                matrix[i][j] = random.choice(list(unique_numbers))
            else:
                matrix[i][j] = random.randint(-100, 100)

    # Calculate the sums of diagonals
    diagonal_1_sum = 0
    diagonal_2_sum = 0
    for i in range(5):
        diagonal_1_sum += matrix[i][i]
        diagonal_2_sum += matrix[i][4-i]

    # Adjust the diagonal sums if necessary
    if diagonal_1_sum < diagonal_2_sum:
        matrix[0][0] += (diagonal_2_sum - diagonal_1_sum)
    elif diagonal_2_sum < diagonal_1_sum:
        matrix[0][4] += (diagonal_1_sum - diagonal_2_sum)

    # Calculate the sum of the first row
    first_row_sum = sum(matrix[0])

    # Adjust the sum of the last column if necessary
    if first_row_sum > sum(matrix[i][4] for i in range(5)):
        matrix[4][4] += (first_row_sum - sum(matrix[i][4] for i in range(5)))

    return matrix

