```swift
func sort(array: [Int]) -> [Int] {
    var currentIndex = 0
    while currentIndex < array.count {
        for j in 0..<array.count - currentIndex - 1 {
            if array[j] > array[j+1] {
                let temp = array[j]
                array[j] = array[j+1]
                array[j + 1] = temp
            }
        }
        currentIndex += 1
    }
    return array
}

