function outputCount = countElementsAboveThreshold()
    % 1. Take a user input of a numerical array
    array = input('Please enter a numerical array: ');

    % Validate user input
    if ~isnumeric(array) || isempty(array)
        error('Input must be a non-empty numerical array.');
    end

    % 2. Randomly shuffle this array
    array = array(randperm(length(array)));

    % 3. Subdivide the array into 5 sub-arrays of equal size
    subArrays = mat2cell(array, 1, subdivisionLengths(length(array), 5));

    % 4. Apply a designated threshold value to each sub-array
    threshold = input('Please enter a threshold value: ');

    % Validate user input
    if ~isnumeric(threshold) || numel(threshold) ~= 1
        error('Threshold must be a numerical scalar.');
    end

    total = 0;
    for i = 1:length(subArrays)
        subArray = subArrays{i};
        count = numel(find(subArray > threshold));
        if count > 1
            count = count * 2;
        end
        total = total + count;
    end

    % 5. Return the total count as the result
    outputCount = total;
end

function lengths = subdivisionLengths(totalLength, numSubdivisions)
    baseLength = floor(totalLength / numSubdivisions);
    remainder = mod(totalLength, numSubdivisions);
    lengths = repmat(baseLength, 1, numSubdivisions);
    lengths(1:remainder) = lengths(1:remainder) + 1;
end
