			if !ok {
				return 0, fmt.Errorf("Отсутствует значение для переменной: %v", token.Value)
			}
			numStack = append(numStack, val)
		case Plus, Minus, Multiply, Divide, Power, Sqrt, Sin, Cos, Tan, Cot:
