		}

		res, err := applyOperation(op, args...)
		if err != nil {
			return 0, err
		}

		numStack = append(numStack, res)
	}

	if len(numStack) != 1 {
		return 0, fmt.Errorf("Неверное количество аргументов")
	}

	return numStack[0], nil
}

