Here is a JavaScript program which uses a Map object to store the frequency of each word starting with the given letter:

```javascript
function wordFrequency(str, letter) {
    let words = str.toLowerCase().split(/\W+/);
    let frequency = new Map();

    for (let word of words) {
        if (word.startsWith(letter)) {
            if (frequency.has(word)) {
                frequency.set(word, frequency.get(word) + 1);
            } else {
                frequency.set(word, 1);
            }
        }
    }

    let obj = Object.create(null);
    for (let [k,v] of frequency) {
        obj[k] = v;
    }

    return obj;
}

